import { C14Provider, useC14, WORLD_NAMES } from './C14Context';
import C14Canvas from './ui/C14Canvas';
import C14Panel from './ui/C14Panel';

const styles = {
  root: {
    display: 'flex',
    flexDirection: 'column',
    height: '100vh',
    background: '#0a0f1a',
    color: '#e5e7eb',
    fontFamily: 'monospace',
    overflow: 'hidden',
  },
  header: {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    padding: '4px 14px',
    background: '#111827',
    borderBottom: '1px solid #1e3a2f',
    flexShrink: 0,
    height: 36,
  },
  title: {
    fontSize: 14,
    fontWeight: 'bold',
    color: '#6ee7b7',
    letterSpacing: 1,
  },
  subtitle: {
    fontSize: 11,
    color: '#4b5563',
  },
  canvasWrapper: {
    flex: 1,
    overflow: 'auto',
    position: 'relative',
  },
  loadingOverlay: {
    position: 'absolute',
    inset: 0,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'rgba(10,15,26,0.85)',
    fontSize: 14,
    color: '#6ee7b7',
    zIndex: 10,
    flexDirection: 'column',
    gap: 10,
  },
};

function Inner() {
  const { loading, tick, worldSeed, worldIds, selectedWorldId, setSelectedWorldId } = useC14();

  return (
    <div style={styles.root}>
      <div style={styles.header}>
        <span style={styles.title}>🌿 CARBONIFÈRE XIV</span>
        {worldIds.map(id => (
          <button
            key={id}
            onClick={() => setSelectedWorldId(id)}
            style={{
              padding: '2px 10px', borderRadius: 4, border: 'none', cursor: 'pointer',
              background: selectedWorldId === id ? '#1d4ed8' : '#1f2937',
              color: selectedWorldId === id ? '#fff' : '#6b7280',
              fontFamily: 'monospace', fontSize: 11,
            }}
          >
            {WORLD_NAMES[id] ?? id}
          </button>
        ))}
        {worldSeed !== null && (
          <span style={{ ...styles.subtitle, marginLeft: 'auto' }}>
            seed {worldSeed} · tick {tick}
          </span>
        )}
      </div>

      <div style={styles.canvasWrapper}>
        {loading && (
          <div style={styles.loadingOverlay}>
            <span>🌱</span>
            <span>Chargement depuis le serveur…</span>
          </div>
        )}
        <C14Canvas />
      </div>

      <C14Panel />
    </div>
  );
}

export default function Carbonifere14() {
  return (
    <C14Provider>
      <Inner />
    </C14Provider>
  );
}
