import { useRef, useEffect, useCallback } from 'react';
import { useC14, GEO_EVENTS, POSITIONED_EVENTS } from '../C14Context';
import { CELL_SIZE } from '../../b13/world/WorldGrid';
import { drawPlants, hitTestFlower } from '../plants/PlantRenderer';
import { hasLiked } from '../persistence/C14PocketBase';

// ── Couleurs terrain ──────────────────────────────────────────────────────────

const TERRAIN_COLORS = {
  eau:      '#4d7a96',
  plaine:   '#b3bd70',
  foret:    '#1e6b30',
  montagne: '#979b9c',
  desert:   '#f0be72',
  marecage: '#bbb17c',
  riviere:  '#2980b9',
  glace:    '#dce9f5',
  neige:    '#b8cbd8',
};

function getEffectiveTerrain(cell, seaLevel) {
  if (cell.altitude < seaLevel) return 'eau';
  if (cell.isRiver)             return 'riviere';

  const { altitude, temperature, humidity } = cell;

  // Glace / neige par température et altitude
  if (temperature < -8)                  return 'glace';
  if (altitude >= 65 && temperature < 3) return 'neige';
  if (altitude >= 58)                    return 'montagne';

  // Zone basse (côtière) : humidité décide entre marécage et plaine
  if (altitude < seaLevel + 10) {
    return humidity > 52 ? 'marecage' : 'plaine';
  }

  // Zone intermédiaire : sec → désert, humide → forêt
  if (humidity < 26) return 'desert';
  if (humidity > 58) return 'foret';

  return humidity > 42 ? 'foret' : 'plaine';
}

function drawGrid(ctx, grid, seaLevel) {
  for (let y = 0; y < grid.rows; y++) {
    for (let x = 0; x < grid.cols; x++) {
      const cell    = grid.getCell(x, y);
      if (!cell) continue;
      const terrain = getEffectiveTerrain(cell, seaLevel);
      ctx.fillStyle = TERRAIN_COLORS[terrain] ?? '#555';
      ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

      // Légère variation d'altitude (ombrage)
      if (cell.altitude > 50 && terrain !== 'eau') {
        const shade = Math.min(0.35, (cell.altitude - 50) / 200);
        ctx.fillStyle = `rgba(255,255,255,${shade})`;
        ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      } else if (cell.altitude < 35 && terrain !== 'eau') {
        const shade = (35 - cell.altitude) / 120;
        ctx.fillStyle = `rgba(0,0,0,${shade * 0.4})`;
        ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      }
    }
  }
}

// ── Composant principal ───────────────────────────────────────────────────────

export default function C14Canvas() {
  const {
    grid, seaLevel, gridVersion,
    plantsRef, plants,
    cellSize,
    activeEvent, applyGeoEvent,
    selectedFlower, setSelectedFlower,
    likeFlower,
  } = useC14();

  const terrainRef  = useRef(null);
  const entityRef   = useRef(null);
  const flowerHitRef = useRef(new Map());

  // ── Dessin du terrain (déclenché sur changement géologique) ──────────────
  useEffect(() => {
    if (!grid || !terrainRef.current) return;
    const canvas  = terrainRef.current;
    const w = grid.cols * CELL_SIZE;
    const h = grid.rows * CELL_SIZE;
    canvas.width  = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d');
    drawGrid(ctx, grid, seaLevel);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [grid, seaLevel, gridVersion]);

  // ── Taille du canvas entités ──────────────────────────────────────────────
  useEffect(() => {
    if (!grid || !entityRef.current) return;
    entityRef.current.width  = grid.cols * CELL_SIZE;
    entityRef.current.height = grid.rows * CELL_SIZE;
  }, [grid]);

  // ── Boucle RAF pour les plantes ───────────────────────────────────────────
  useEffect(() => {
    if (!grid) return;
    let rafId;

    function animate() {
      const canvas = entityRef.current;
      if (canvas && canvas.width > 0) {
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawPlants(
          ctx,
          plantsRef.current,
          CELL_SIZE,
          selectedFlower?.id ?? null,
          flowerHitRef.current,
        );
      }
      rafId = requestAnimationFrame(animate);
    }

    rafId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(rafId);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [grid, selectedFlower]);

  // ── Clic sur le canvas ────────────────────────────────────────────────────
  const handleClick = useCallback((e) => {
    const canvas = entityRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();

    // Événement géologique positionné
    if (activeEvent && POSITIONED_EVENTS.has(activeEvent)) {
      const cellX = Math.floor((e.clientX - rect.left) / cellSize);
      const cellY = Math.floor((e.clientY - rect.top)  / cellSize);
      applyGeoEvent(activeEvent, cellX, cellY);
      return;
    }

    // Hit test fleur
    const hit = hitTestFlower(e.clientX, e.clientY, rect, cellSize, flowerHitRef.current);
    if (hit) {
      setSelectedFlower(hit);
    } else {
      setSelectedFlower(null);
    }
  }, [activeEvent, applyGeoEvent, cellSize, setSelectedFlower]);

  if (!grid) {
    return (
      <div style={{
        width: '100%', height: '100%',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        color: '#4b5563', fontFamily: 'monospace', fontSize: 14,
      }}>
        Génération du monde carbonifère…
      </div>
    );
  }

  const w    = grid.cols * CELL_SIZE;
  const h    = grid.rows * CELL_SIZE;
  const zoom = cellSize / CELL_SIZE;

  const isPlacing = activeEvent && POSITIONED_EVENTS.has(activeEvent);

  return (
    <div style={{ width: w * zoom, height: h * zoom, flexShrink: 0, position: 'relative' }}>
      <div style={{
        position: 'relative', width: w, height: h,
        transform: `scale(${zoom})`, transformOrigin: 'top left',
      }}>
        {/* Terrain */}
        <canvas
          ref={terrainRef}
          style={{ position: 'absolute', top: 0, left: 0, filter: 'blur(8px)' }}
        />
        {/* Plantes */}
        <canvas
          ref={entityRef}
          onClick={handleClick}
          style={{
            position: 'absolute', top: 0, left: 0,
            imageRendering: 'pixelated',
            cursor: isPlacing ? 'crosshair' : 'pointer',
          }}
        />
      </div>
    </div>
  );
}
