import { useState, useRef } from 'react';
import { useC14, GEO_EVENTS, POSITIONED_EVENTS } from '../C14Context';

const s = {
  panel: {
    display: 'flex', flexWrap: 'wrap', alignItems: 'center',
    gap: 8, padding: '6px 12px',
    background: '#111827', borderTop: '1px solid #374151',
    fontFamily: 'monospace', fontSize: 12, color: '#e5e7eb',
    minHeight: 44,
  },
  btn: (active, color = '#374151') => ({
    padding: '3px 10px', borderRadius: 4, border: 'none', cursor: 'pointer',
    background: active ? (color || '#2563eb') : '#1f2937',
    color: active ? '#fff' : '#9ca3af',
    fontFamily: 'monospace', fontSize: 11, transition: 'background 0.15s',
  }),
  sep: { width: 1, height: 24, background: '#374151', margin: '0 4px' },
  stat: { color: '#6ee7b7', minWidth: 24 },
  label: { color: '#6b7280', marginRight: 2 },
  likeBox: {
    background: '#1f2937', border: '1px solid #374151', borderRadius: 6,
    padding: '6px 10px', display: 'flex', flexDirection: 'column', gap: 4,
    minWidth: 160,
  },
  likeBtn: (liked) => ({
    padding: '4px 12px', borderRadius: 4, border: 'none', cursor: liked ? 'default' : 'pointer',
    background: liked ? '#065f46' : '#7c3aed',
    color: '#fff', fontFamily: 'monospace', fontSize: 11,
    opacity: liked ? 0.7 : 1,
  }),
};

const GEO_LABELS = {
  [GEO_EVENTS.VOLCANO]:        '🌋 Volcan',
  [GEO_EVENTS.EARTHQUAKE]:     '🌍 Séisme',
  [GEO_EVENTS.METEOR]:         '☄️ Météorite',
  [GEO_EVENTS.MOUNTAIN_RANGE]: '⛰️ Montagne',
  [GEO_EVENTS.FLOOD]:          '🌊 Inondation',
  [GEO_EVENTS.DROUGHT]:        '☀️ Sécheresse',
  [GEO_EVENTS.WARMING]:        '🔥 Réchauffement',
  [GEO_EVENTS.GLACIATION]:     '❄️ Glaciation',
};

const SPEED_LABELS = ['⏸', '🐢', '🚶', '🚴', '⚡'];

export default function C14Panel() {
  const {
    tick, speed, setSpeed, isRunning, toggleRun,
    statsCache, cellSize, setCellSize,
    activeEvent, setActiveEvent, applyGeoEvent,
    hasLiked,
    selectedFlower, setSelectedFlower,
    likeFlower, lastSaved,
    plants,
  } = useC14();

  const [likeResult, setLikeResult] = useState(null);
  const [liking, setLiking] = useState(false);
  const prevFlowerIdRef = useRef(null);
  if (selectedFlower?.id !== prevFlowerIdRef.current) {
    prevFlowerIdRef.current = selectedFlower?.id ?? null;
    if (likeResult !== null) setLikeResult(null);
  }

  const handleLike = async () => {
    if (!selectedFlower || liking) return;
    setLiking(true);
    const result = await likeFlower(selectedFlower.plantId, selectedFlower.id);
    setLikeResult(result);
    setLiking(false);
  };

  // Trouve la fleur sélectionnée pour afficher ses infos
  const selectedPlant  = selectedFlower ? plants.find(p => p.id === selectedFlower.plantId) : null;
  const selectedFl     = selectedPlant?.flowers.find(f => f.id === selectedFlower?.id);
  const alreadyLiked   = selectedFlower ? hasLiked(selectedFlower.plantId, selectedFlower.id) : false;

  return (
    <div style={s.panel}>
      {/* Lecture / vitesse */}
      <button style={s.btn(isRunning, '#16a34a')} onClick={toggleRun}>
        {isRunning ? '⏸ Pause' : '▶ Run'}
      </button>

      {[1, 2, 3, 4].map(v => (
        <button key={v} style={s.btn(speed === v)} onClick={() => setSpeed(v)}>
          {SPEED_LABELS[v]}
        </button>
      ))}

      <div style={s.sep} />

      {/* Stats */}
      <span><span style={s.label}>tick</span><span style={s.stat}>{tick}</span></span>
      <span><span style={s.label}>plantes</span><span style={s.stat}>{statsCache.alive}</span></span>
      <span><span style={s.label}>fleurs</span><span style={s.stat}>{statsCache.flowers}</span></span>
      <span><span style={s.label}>fruits</span><span style={s.stat}>{statsCache.fruits}</span></span>

      <div style={s.sep} />

      {/* Zoom */}
      <span style={s.label}>zoom</span>
      <button style={s.btn(false)} onClick={() => setCellSize(cellSize - 2)}>−</button>
      <span style={{ color: '#9ca3af', minWidth: 24, textAlign: 'center' }}>{cellSize}</span>
      <button style={s.btn(false)} onClick={() => setCellSize(cellSize + 2)}>+</button>

      <div style={s.sep} />

      {/* Événements géologiques */}
      {Object.entries(GEO_LABELS).map(([type, label]) => (
        <button
          key={type}
          style={s.btn(activeEvent === type, '#b45309')}
          onClick={() => {
            if (POSITIONED_EVENTS.has(type)) {
              setActiveEvent(activeEvent === type ? null : type);
            } else {
              applyGeoEvent(type, null, null);
            }
          }}
          title={type}
        >
          {label}
        </button>
      ))}

      <div style={s.sep} />

      {/* Like box */}
      {selectedFl ? (
        <div style={s.likeBox}>
          <span style={{ color: '#e5e7eb', fontSize: 11 }}>
            🌸 Fleur sélectionnée — {selectedFl.likes || 0} ♥
          </span>
          {selectedPlant && (
            <span style={{ color: '#9ca3af', fontSize: 10 }}>
              Plante #{selectedFlower.plantId.slice(-6)} · {selectedPlant.likes} likes total
            </span>
          )}
          {alreadyLiked || likeResult?.ok ? (
            <span style={{ color: '#6ee7b7', fontSize: 11 }}>✓ Déjà likée</span>
          ) : (
            <button style={s.likeBtn(false)} onClick={handleLike} disabled={liking}>
              {liking ? '…' : '♥ Liker cette fleur'}
            </button>
          )}
          <button
            style={{ ...s.btn(false), fontSize: 10, padding: '2px 6px', marginTop: 2 }}
            onClick={() => { setSelectedFlower(null); setLikeResult(null); }}
          >
            ✕ Désélectionner
          </button>
        </div>
      ) : (
        <span style={{ color: '#4b5563', fontSize: 11, fontStyle: 'italic' }}>
          Clic sur une fleur pour liker
        </span>
      )}

      {/* Dernière sauvegarde */}
      {lastSaved && (
        <span style={{ color: '#4b5563', fontSize: 10, marginLeft: 'auto' }}>
          💾 {lastSaved.toLocaleTimeString()}
        </span>
      )}
    </div>
  );
}
